def fix_feishu_option_sort_key(options):
    """Call when Feishu schema options sort nondeterministically or fail around mixed color types; applies the patched sort key with a color-type rank tiebreaker."""
    def sort_key(option):
        color = getattr(option, "color", None)
        return (
            getattr(option, "name", ""),
            getattr(option, "option_id", None) or "",
            "" if color is None else str(color),
            0 if color is None else (1 if isinstance(color, int) else 2),
        )

    return tuple(sorted(options, key=sort_key))
